INSERT INTO pms_sku (product_id, sku_code, price, compare_at_price, stock, pic, images, description, specs, status) VALUES ((SELECT id FROM pms_product WHERE slug = 'isinwheel-s9-pneumatic-tireelectric-scooter-electric-scooters-for-kids'), '5777980-ELECTRIC-SCOOTERS-FOR-KIDS-19-2-5A63BAFF348B', '489.99', '999.99', 0, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/S9.35_87e54ec1-e4b7-43f7-8bb0-985bf0fab004.jpg?v=1762411995', '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/S9.35_87e54ec1-e4b7-43f7-8bb0-985bf0fab004.jpg?v=1762411995"]'::jsonb, '{"en": "isinwheel S9 Pro Pneumatic Tire Electric Scooter - 2026 Upgraded Edition / S9 Pro*2", "zh": "isinwheel S9 Pro Pneumatic Tire Electric Scooter - 2026 Upgraded Edition / S9 Pro*2"}'::jsonb, '{"en": {"style": "2026 Upgraded Edition", "buy more save more": "S9 Pro*2"}, "zh": {"style": "2026 Upgraded Edition", "buy more save more": "S9 Pro*2"}}'::jsonb, 'INACTIVE') ON CONFLICT (sku_code) DO UPDATE SET product_id = EXCLUDED.product_id, price = EXCLUDED.price, compare_at_price = EXCLUDED.compare_at_price, stock = EXCLUDED.stock, pic = EXCLUDED.pic, images = EXCLUDED.images, description = EXCLUDED.description, specs = EXCLUDED.specs, status = EXCLUDED.status, update_time = CURRENT_TIMESTAMP;
INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (19, 'isinwheel-s9-pro-electric-scooter-1-electric-scooters-for-kids', '{"en": "isinwheel S9Pro Electric Scooter 350W", "zh": "isinwheel S9Pro Electric Scooter 350W"}'::jsonb, '{"en": "Scooter for Kids", "zh": "Scooter for Kids"}'::jsonb, '{"en": "<p>The iSinwheel S9Pro is a 350W electric scooter designed to provide a perfect balance of speed, efficiency, and comfort. Its sleek design, reliable power output, and smooth ride make it a great choice for daily urban commuting and short trips.</p>\n<p> </p>\n<img data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/05c1749392567beef34c8b7bbb8c21ac_349fd0a5-731e-4fb6-800d-612e8b4f1430.png?v=1615529880\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/05c1749392567beef34c8b7bbb8c21ac_349fd0a5-731e-4fb6-800d-612e8b4f1430.png?v=1615529880\"><span data-mce-fragment=\"1\">Max speed 18.6mph (30km/h)</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/06600783af0273abb34e0a0afee8a06b_41f17ca0-7d62-4c3d-a4f8-783805cac284.png?v=1615530248\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/06600783af0273abb34e0a0afee8a06b_41f17ca0-7d62-4c3d-a4f8-783805cac284.png?v=1615530248\"><span data-mce-fragment=\"1\">Max range 15.5 miles (25km)</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/3b49dcc1eb4b18b6fa150e99d1621f22.png?v=1615530287\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/3b49dcc1eb4b18b6fa150e99d1621f22.png?v=1615530287\"><span data-mce-fragment=\"1\">8.5inch Honeycomb solid tire</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/d61752e527354608fb4d7a948fab462a.png?v=1615530376\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/d61752e527354608fb4d7a948fab462a.png?v=1615530376\"><span data-mce-fragment=\"1\">Electronic brake + rear wheel foot brake</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/dda55bc491a2e0f7e006208960c1de12.png?v=1615530475\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/dda55bc491a2e0f7e006208960c1de12.png?v=1615530475\"><span data-mce-fragment=\"1\">Front and rear lights</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/c3a04563d2e18ea66a0fbcd039e3eba6.png?v=1615530513\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/c3a04563d2e18ea66a0fbcd039e3eba6.png?v=1615530513\"><span data-mce-fragment=\"1\">Maximum degree of climbing 20 °</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/07e7d50cfc079991c520aed349ba6b7a.png?v=1615530541\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/07e7d50cfc079991c520aed349ba6b7a.png?v=1615530541\"><span data-mce-fragment=\"1\">IP54 Waterproof levels</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopify.com/s/files/1/0536/2417/6817/files/weight.jpg?v=1616656577\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopify.com/s/files/1/0536/2417/6817/files/weight.jpg?v=1616656577\"><span data-mce-fragment=\"1\">Max load 264lbs</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopify.com/s/files/1/0536/2417/6817/files/c8577a1df210126991a8c79837c61c3f.jpg?v=1616656603\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopify.com/s/files/1/0536/2417/6817/files/c8577a1df210126991a8c79837c61c3f.jpg?v=1616656603\"><span data-mce-fragment=\"1\">With APP</span>", "zh": "<p>The iSinwheel S9Pro is a 350W electric scooter designed to provide a perfect balance of speed, efficiency, and comfort. Its sleek design, reliable power output, and smooth ride make it a great choice for daily urban commuting and short trips.</p>\n<p> </p>\n<img data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/05c1749392567beef34c8b7bbb8c21ac_349fd0a5-731e-4fb6-800d-612e8b4f1430.png?v=1615529880\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/05c1749392567beef34c8b7bbb8c21ac_349fd0a5-731e-4fb6-800d-612e8b4f1430.png?v=1615529880\"><span data-mce-fragment=\"1\">Max speed 18.6mph (30km/h)</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/06600783af0273abb34e0a0afee8a06b_41f17ca0-7d62-4c3d-a4f8-783805cac284.png?v=1615530248\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/06600783af0273abb34e0a0afee8a06b_41f17ca0-7d62-4c3d-a4f8-783805cac284.png?v=1615530248\"><span data-mce-fragment=\"1\">Max range 15.5 miles (25km)</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/3b49dcc1eb4b18b6fa150e99d1621f22.png?v=1615530287\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/3b49dcc1eb4b18b6fa150e99d1621f22.png?v=1615530287\"><span data-mce-fragment=\"1\">8.5inch Honeycomb solid tire</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/d61752e527354608fb4d7a948fab462a.png?v=1615530376\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/d61752e527354608fb4d7a948fab462a.png?v=1615530376\"><span data-mce-fragment=\"1\">Electronic brake + rear wheel foot brake</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.