INSERT INTO pms_sku (product_id, sku_code, price, compare_at_price, stock, pic, images, description, specs, status) VALUES ((SELECT id FROM pms_product WHERE slug = 'isinwheel-gt2-off-road-electric-scooter-peak-1000w-electric-scooters-for-kids'), '3949030-ELECTRIC-SCOOTERS-FOR-KIDS-24-2-1C9ECC539435', '649.99', '999.99', 20, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/2_455f9f56-46cf-4f69-bf01-1cde85bc9958.jpg?v=1747994278', '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/2_455f9f56-46cf-4f69-bf01-1cde85bc9958.jpg?v=1747994278"]'::jsonb, '{"en": "isinwheel GT2 1000W Off Road Electric Scooter 2026 Upgraded Version - GT2 with Seat / Scooter Bag", "zh": "isinwheel GT2 1000W Off Road Electric Scooter 2026 Upgraded Version - GT2 with Seat / Scooter Bag"}'::jsonb, '{"en": {"style": "GT2 with Seat", "free gift included": "Scooter Bag"}, "zh": {"style": "GT2 with Seat", "free gift included": "Scooter Bag"}}'::jsonb, 'ACTIVE') ON CONFLICT (sku_code) DO UPDATE SET product_id = EXCLUDED.product_id, price = EXCLUDED.price, compare_at_price = EXCLUDED.compare_at_price, stock = EXCLUDED.stock, pic = EXCLUDED.pic, images = EXCLUDED.images, description = EXCLUDED.description, specs = EXCLUDED.specs, status = EXCLUDED.status, update_time = CURRENT_TIMESTAMP;
INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (19, 'isinwheel-gt2-800w-off-road-electric-scooter-electric-scooters-for-kids', '{"en": "isinwheel GT2 Off Road Electric Scooter 2026 Upgraded Version", "zh": "isinwheel GT2 Off Road Electric Scooter 2026 Upgraded Version"}'::jsonb, '{"en": "Scooter for Kids", "zh": "Scooter for Kids"}'::jsonb, '{"en": "<p>The Isinwheel GT2, with its powerful 800W motor, is an off-road electric scooter designed to conquer rough terrains with ease. Its robust construction and pneumatic tires ensure a smooth, durable ride, making it a versatile choice for adventurers and city commuters alike.<br></p>\n<p>【Experience Ultimate Power &amp; Speed】The GT2 folding electric scooter boasts an impressive 800W brushless motor, delivering rapid acceleration and exceptional climbing prowess. With a top speed of 28MPH and the ability to conquer slopes up to 35°, this scooter''s 1000W power ensures effortless maneuvering across all terrains, simplifying your daily commute or mountain escapades.<br data-mce-fragment=\"1\"><br data-mce-fragment=\"1\">【Extended Range &amp; Enduring Battery】Equipped with a 48V/15Ah lithium-ion battery, the isinwheel GT2 electric scooter offers an extensive range of up to 28 miles on standard Mode. Its adaptable 3-speed modes - ranging from 0-10MPH, 0-18MPH, to 0-28MPH - provide an exhilarating and customizable riding experience.<br data-mce-fragment=\"1\"><br data-mce-fragment=\"1\">【Cutting-Edge 2023 Model】The newly released GT2 electric scooter introduces a smart LCD meter that displays real-time information, including speed, speed mode, and battery life. With a comprehensive 360-degree lighting system, encompassing dual headlights, side lights, rear turn signals, and a brake light, you can confidently navigate night rides with enhanced visibility and safety.<br data-mce-fragment=\"1\"><br data-mce-fragment=\"1\">【Off-Road Adventure &amp; Superior Suspension】Unleash your adventurous spirit with the 11-inch pneumatic off-road tires, offering exceptional shock absorption, anti-skid capabilities, and precise control for off-road excursions. The front and rear independent suspension systems work harmoniously to absorb the impact of uneven surfaces, ensuring a smooth and comfortable ride even on rugged roads. With a maximum load capacity of 330 lbs, this scooter accommodates a range of riders.<br data-mce-fragment=\"1\"><br data-mce-fragment=\"1\">【Efficient Braking &amp; Convenient Folding】Designed for utmost safety and convenience, the isinwheel GT2 features a hydraulic brake system and quadruple absorbent systems, enhancing your riding security. Its foldable design facilitates easy storage in car trunks or hassle-free transportation on public transit, making it an ideal travel companion.</p>", "zh": "<p>The Isinwheel GT2, with its powerful 800W motor, is an off-road electric scooter designed to conquer rough terrains with ease. Its robust construction and pneumatic tires ensure a smooth, durable ride, making it a versatile choice for adventurers and city commuters alike.<br></p>\n<p>【Experience Ultimate Power &amp; Speed】The GT2 folding electric scooter boasts an impressive 800W brushless motor, delivering rapid acceleration and exceptional climbing prowess. With a top speed of 28MPH and the ability to conquer slopes up to 35°, this scooter''s 1000W power ensures effortless maneuvering across all terrains, simplifying your daily commute or mountain escapades.<br data-mce-fragment=\"1\"><br data-mce-fragment=\"1\">【Extended Range &amp; Enduring Battery】Equipped with a 48V/15Ah lithium-ion battery, the isinwheel GT2 electric scooter offers an extensive range of up to 28 miles on standard Mode. Its adaptable 3-speed modes - ranging from 0-10MPH, 0-18MPH, to 0-28MPH - provide an exhilarating and customizable riding experience.<br data-mce-fragment=\"1\"><br data-mce-fragment=\"1\">【Cutting-Edge 2023 Model】The newly released GT2 electric scooter introduces a smart LCD meter that displays real-time information, including speed, speed mode, and battery life. With a comprehensive 360-degree lighting system, encompassing dual headlights, side lights, rear turn signals, and a brake light, you can confidently navigate night rides with enhanced visibility and safety.<br data-mce-fragment=\"1\"><br data-mce-fragment=\"1\">【Off-Road Adventure &amp; Superior Suspension】Unleash your adventurous spirit with the 11-inch pneumatic off-road tires, offering exceptional shock absorption, anti-skid capabilities, and precise control for off-road excursions. The front and rear independent suspension systems work harmoniously to absorb the impact of uneven surfaces, ensuring a smooth and comfortable ride even on rugged roads. With a maximum load capacity of 330 lbs, this scooter accommodates a range of riders.<br data-mce-fragment=\"1\"><br data-mce-fragment=\"1\">【Efficient Braking &amp; Convenient Folding】Designed for utmost safety and convenience, the isinwheel GT2 features a hydraulic brake system and quadruple absorbent systems, enhancing your riding security. Its foldable design facilitates easy storage in car trunks or hassle-free transportation on public transit, making it an ideal travel companion.</p>"}'::jsonb, '669.99', '999.99', 20, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/lQLPJwx0iW1QXInNBkDNBkCwTZiISLr4veYIMjuC_gYpAA_1600_1600.png?v=1752828599', FALSE, '{"en": ["Spring Sale"], "zh": ["Spring Sale"]}'::jsonb, '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/lQLPJwx0iW1QXInNBkDNBkCwTZiISLr4veYIMjuC_gYpAA_1600_1600.png?v=1752828599", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1600X16002.jpg?v=1752828599", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/61nQXIaf9sL._AC_SL1500_14be181d-9b93-47e4-8b85-eb3780deb580.jpg?v=1752828599", "htt