INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (12, 's9-electric-scooter-350w-all-terrain-electric-scooter', '{"en": "S9 Electric Scooter 350W", "zh": "S9 Electric Scooter 350W"}'::jsonb, '{"en": "Off Road Scooter", "zh": "Off Road Scooter"}'::jsonb, '{"en": "<p>The iSinwheel S9 is a 350W electric scooter designed to provide a perfect balance of speed, efficiency, and comfort. Its sleek design, reliable power output, and smooth ride make it a great choice for daily urban commuting and short trips.</p>\n<p> </p>\n<p><img data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/05c1749392567beef34c8b7bbb8c21ac_349fd0a5-731e-4fb6-800d-612e8b4f1430.png?v=1615529880\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">Max speed 18.6mph (30km/h)</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/06600783af0273abb34e0a0afee8a06b_41f17ca0-7d62-4c3d-a4f8-783805cac284.png?v=1615530248\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">Max range 15.5 miles (25km)</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/3b49dcc1eb4b18b6fa150e99d1621f22.png?v=1615530287\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">8.5inch Honeycomb solid tire</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/d61752e527354608fb4d7a948fab462a.png?v=1615530376\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">Electronic brake + rear wheel foot brake</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/dda55bc491a2e0f7e006208960c1de12.png?v=1615530475\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">Front and rear lights</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/c3a04563d2e18ea66a0fbcd039e3eba6.png?v=1615530513\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">Maximum degree of climbing 20 °</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/07e7d50cfc079991c520aed349ba6b7a.png?v=1615530541\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">IP54 Waterproof levels</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopify.com/s/files/1/0536/2417/6817/files/weight.jpg?v=1616656577\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">Max load 264lbs</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopify.com/s/files/1/0536/2417/6817/files/c8577a1df210126991a8c79837c61c3f.jpg?v=1616656603\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">With APP</span></p>", "zh": "<p>The iSinwheel S9 is a 350W electric scooter designed to provide a perfect balance of speed, efficiency, and comfort. Its sleek design, reliable power output, and smooth ride make it a great choice for daily urban commuting and short trips.</p>\n<p> </p>\n<p><img data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/05c1749392567beef34c8b7bbb8c21ac_349fd0a5-731e-4fb6-800d-612e8b4f1430.png?v=1615529880\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">Max speed 18.6mph (30km/h)</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/06600783af0273abb34e0a0afee8a06b_41f17ca0-7d62-4c3d-a4f8-783805cac284.png?v=1615530248\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">Max range 15.5 miles (25km)</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/3b49dcc1eb4b18b6fa150e99d1621f22.png?v=1615530287\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">8.5inch Honeycomb solid tire</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/d61752e527354608fb4d7a948fab462a.png?v=1615530376\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">Electronic brake + rear wheel foot brake</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/dda55bc491a2e0f7e006208960c1de12.png?v=1615530475\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">Front and rear lights</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/c3a04563d2e18ea66a0fbcd039e3eba6.png?v=1615530513\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">Maximum degree of climbing 20 °</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/07e7d50cfc079991c520aed349ba6b7a.png?v=1615530541\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">IP54 Waterproof levels</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopify.com/s/files/1/0536/2417/6817/files/weight.jpg?v=1616656577\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">Max load 264lbs</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopify.com/s/files/1/0536/2417/6817/files/c8577a1df210126991a8c79837c61c3f.jpg?v=1616656603\" data-mce-fragment=\"1\"><span data-mce-fragment=\"1\">With APP</span></p>"}'::jsonb, '219.99', '399.99', 20, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_368de45c-9a01-4a1f-9db5-feb7aa86c7db.jpg?v=1775119225', TRUE, '{"en": ["NEW", "Spring Sale"], "zh": ["NEW", "Spring Sale"]}'::jsonb, '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_368de45c-9a01-4a1f-9db5-feb7aa86c7db.jpg?v=1775119225", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_2_31191d4c-b7f0-4681-b939-65766ce2a635.jpg?v=1773655055", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/2_2_e00e5d82-d6e2-42bc-9023-ee32b0e14504.jpg?v=1773655055", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/3_2_5ae36de5-027b-4d2a-bf34-47424c153a68.jpg?v=1773653310", "https://cdn.shopify.com