INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (12, 'isinwheel-gt2-off-road-electric-scooter-peak-1000w-all-terrain-electric-scooter-2', '{"en": "isinwheel GT2 1000W Off Road Electric Scooter 2026 Upgraded Version - Trail Edition 2", "zh": "isinwheel GT2 1000W Off Road Electric Scooter 2026 Upgraded Version - Trail Edition 2"}'::jsonb, '{"en": "Off Road Scooter / Trail Edition 2", "zh": "Off Road Scooter / Trail Edition 2"}'::jsonb, '{"en": "<div class=\"product-block\" data-mce-fragment=\"1\">\n<div class=\"rte\" data-mce-fragment=\"1\">\n<div style=\"text-align: left;\" data-mce-fragment=\"1\" data-mce-style=\"text-align: left;\">\n<h3 data-mce-fragment=\"1\">\n<strong> The ultimate all-terrain electric scooter</strong><br>\n</h3>\n<p style=\"display: flex; align-items: center;\" data-mce-fragment=\"1\" data-mce-style=\"display: flex; align-items: center;\"><span style=\"font-size: 0.875rem;\"><strong>isinwheel GT2 off-road scooter starts a whole new perspective where a scooter could be the new sports equipment. The GT2 comes with a cyberpunk design concept and a structure that uses aircraft-grade magnesium alloy that can support a maximum payload of 330lbs. Safety is not an issue as the gt2 off road electric scooter uses front and rear disc brakes on self-healing 11-inch pneumatic off road Tires. The gt2 can accelerate up to 28mph and has a super long range of around 28 miles, making it the most powerful and best off road electric scooter ever released. This high-performance, high-tech model is sure to turn heads your way</strong></span></p>\n<div style=\"display: flex; align-items: center;\" data-mce-fragment=\"1\" data-mce-style=\"display: flex; align-items: center;\"><br data-mce-fragment=\"1\"></div>\n</div>\n</div>\n</div>\n<div class=\"product-block\" data-mce-fragment=\"1\">\n<div class=\"product-form__texts\" data-mce-fragment=\"1\">\n<div class=\"product_form__text_tabs\" data-mce-fragment=\"1\">\n<div class=\"active::after active\" data-mce-fragment=\"1\"></div>\n</div>\n</div>\n</div><p>Trail Edition 2 for the off road scooter catalog.</p>", "zh": "<div class=\"product-block\" data-mce-fragment=\"1\">\n<div class=\"rte\" data-mce-fragment=\"1\">\n<div style=\"text-align: left;\" data-mce-fragment=\"1\" data-mce-style=\"text-align: left;\">\n<h3 data-mce-fragment=\"1\">\n<strong> The ultimate all-terrain electric scooter</strong><br>\n</h3>\n<p style=\"display: flex; align-items: center;\" data-mce-fragment=\"1\" data-mce-style=\"display: flex; align-items: center;\"><span style=\"font-size: 0.875rem;\"><strong>isinwheel GT2 off-road scooter starts a whole new perspective where a scooter could be the new sports equipment. The GT2 comes with a cyberpunk design concept and a structure that uses aircraft-grade magnesium alloy that can support a maximum payload of 330lbs. Safety is not an issue as the gt2 off road electric scooter uses front and rear disc brakes on self-healing 11-inch pneumatic off road Tires. The gt2 can accelerate up to 28mph and has a super long range of around 28 miles, making it the most powerful and best off road electric scooter ever released. This high-performance, high-tech model is sure to turn heads your way</strong></span></p>\n<div style=\"display: flex; align-items: center;\" data-mce-fragment=\"1\" data-mce-style=\"display: flex; align-items: center;\"><br data-mce-fragment=\"1\"></div>\n</div>\n</div>\n</div>\n<div class=\"product-block\" data-mce-fragment=\"1\">\n<div class=\"product-form__texts\" data-mce-fragment=\"1\">\n<div class=\"product_form__text_tabs\" data-mce-fragment=\"1\">\n<div class=\"active::after active\" data-mce-fragment=\"1\"></div>\n</div>\n</div>\n</div><p>Trail Edition 2 for the off road scooter catalog.</p>"}'::jsonb, '642.59', '1019.99', 43, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/2_455f9f56-46cf-4f69-bf01-1cde85bc9958.jpg?v=1747994278', FALSE, '{"en": ["HOT", "Spring Sale"], "zh": ["HOT", "Spring Sale"]}'::jsonb, '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/2_455f9f56-46cf-4f69-bf01-1cde85bc9958.jpg?v=1747994278", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1600X16002_0ec64bf0-73a8-4013-b0ce-5931897e8923.jpg?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/61nQXIaf9sL._AC_SL1500.jpg?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/71hQPhncnaL._AC_SL1500.jpg?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_4_751b36f7-7d90-43b2-b09f-8753d5d84be4.jpg?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/GT2-NewOffRoadE-Scooter_5d1ce4f9-1cae-47da-bb0a-9644202f8624.jpg?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/3C923E8A-EDFB-45f5-9D53-D44014E05CF2_c5c5b43e-d27f-49c1-9624-504d0b51d5cd.png?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/67242218-39DB-46c4-A1E8-A3EA433FE7FF_ec0a9a37-ec92-46fa-9a30-cda14e9eff52.png?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/D06FB225-E7EB-4ac7-88D6-3874A0594E0A_0d4113aa-a41c-490b-bc85-0749b2cb0ff0.png?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/ED283995-787B-4c73-AD38-41E4AF011864_3f6422b4-8c64-4d30-a624-ad86d096827b.png?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_2_acf82225-9548-47c6-9ace-0a7d05db11e6.jpg?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_5_1b8006c6-3464-4682-a2d8-438a6263e553.jpg?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_5687e9da-7211-4b86-b1d0-0cb1be4c86e3.jpg?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_3521136a-5f94-4595-920f-36dee3b6f52f.jpg?v=1750241254", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_3_dfa15daf-723e-408b-bb81-174b266bfef7.jpg?v=