INSERT INTO pms_sku (product_id, sku_code, price, compare_at_price, stock, pic, images, description, specs, status) VALUES ((SELECT id FROM pms_product WHERE slug = 'isinwheel-hyper-x-700w-electric-scooter-with-seat-all-terrain-electric-scooter-2'), '4705342-ALL-TERRAIN-ELECTRIC-SCOOTER-42-5-E73042A4A833', '866.99', '886.99', 20, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1-12.jpg?v=1734419841', '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1-12.jpg?v=1734419841"]'::jsonb, '{"en": "isinwheel Hyper X 700W Electric Scooter with Seat & Basket - White+Black / Trail Edition 2", "zh": "isinwheel Hyper X 700W Electric Scooter with Seat & Basket - White+Black / Trail Edition 2"}'::jsonb, '{"en": {"style": "White+Black"}, "zh": {"style": "White+Black"}}'::jsonb, 'ACTIVE') ON CONFLICT (sku_code) DO UPDATE SET product_id = EXCLUDED.product_id, price = EXCLUDED.price, compare_at_price = EXCLUDED.compare_at_price, stock = EXCLUDED.stock, pic = EXCLUDED.pic, images = EXCLUDED.images, description = EXCLUDED.description, specs = EXCLUDED.specs, status = EXCLUDED.status, update_time = CURRENT_TIMESTAMP;
INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (12, 'isinwheel-s9-electric-scooter-all-terrain-electric-scooter-2', '{"en": "isinwheel S9 Series Electric Scooter - Trail Edition 2", "zh": "isinwheel S9 Series Electric Scooter - Trail Edition 2"}'::jsonb, '{"en": "Off Road Scooter / Trail Edition 2", "zh": "Off Road Scooter / Trail Edition 2"}'::jsonb, '{"en": "<span>iSinwheel® S9 is a 350W electric scooter designed to offer a seamless blend of speed, efficiency, and convenience for daily commuting. Its lightweight design and reliable power output make it an ideal choice for navigating through urban environments with ease.</span>\n<ul data-mce-fragment=\"1\">\n<li data-mce-fragment=\"1\">\n<strong data-mce-fragment=\"1\">Excellent Performance</strong>: Toggle between saving comfort mode and sport mode. Comfort Mode propels the scooter at a speed of 15mph. While sport mode propels it at a high speed of 18mph. </li>\n<li data-mce-fragment=\"1\">\n<strong data-mce-fragment=\"1\">Powerful Motor</strong>: The scooter is equipped with a powerful 350W motor, which can maximize the distance of each ride, rolling slopes up to 20°. 7500mAh high-capacity battery, the maximum travel distance of up to 15.5miles, the charging time 4-5H. The built-in dual braking system and anti-vibration device provide you with a high speed and stable riding experience.</li>\n<li data-mce-fragment=\"1\">\n<strong data-mce-fragment=\"1\">Lightweight</strong>: The scooter weighs only 12.5kg. The lightweight and foldable design are easy to carry and store, realizes 3 seconds of folding. i9 scooter fits in the trunk of most cars so you can bring it wherever you want to rid.</li>\n<li data-mce-fragment=\"1\">\n<strong data-mce-fragment=\"1\">Durability</strong>: 8.5″ Pneumatic tire no worry air leakage. Waterproof IP54 allows you to drive in rain. The control panel displays the speed, gear, mileage, and battery level.</li>\n<li data-mce-fragment=\"1\">\n<strong data-mce-fragment=\"1\">Fast Delivery and Warranty</strong>: Deliver within 2 to 5 business days. The e-scooter can be used for commuting or short-distance travel and is also an ideal gift for your friends and family. We provide a 180 days after-sales guarantee. If you have any questions about this product, please contact us at any time, and we will reply to you within 24 hours.</li>\n</ul>\n<div id=\"gtx-trans\" style=\"position: absolute; left: -18px; top: -18.4062px;\">\n<div class=\"gtx-trans-icon\"></div>\n</div><p>Trail Edition 2 for the off road scooter catalog.</p>", "zh": "<span>iSinwheel® S9 is a 350W electric scooter designed to offer a seamless blend of speed, efficiency, and convenience for daily commuting. Its lightweight design and reliable power output make it an ideal choice for navigating through urban environments with ease.</span>\n<ul data-mce-fragment=\"1\">\n<li data-mce-fragment=\"1\">\n<strong data-mce-fragment=\"1\">Excellent Performance</strong>: Toggle between saving comfort mode and sport mode. Comfort Mode propels the scooter at a speed of 15mph. While sport mode propels it at a high speed of 18mph. </li>\n<li data-mce-fragment=\"1\">\n<strong data-mce-fragment=\"1\">Powerful Motor</strong>: The scooter is equipped with a powerful 350W motor, which can maximize the distance of each ride, rolling slopes up to 20°. 7500mAh high-capacity battery, the maximum travel distance of up to 15.5miles, the charging time 4-5H. The built-in dual braking system and anti-vibration device provide you with a high speed and stable riding experience.</li>\n<li data-mce-fragment=\"1\">\n<strong data-mce-fragment=\"1\">Lightweight</strong>: The scooter weighs only 12.5kg. The lightweight and foldable design are easy to carry and store, realizes 3 seconds of folding. i9 scooter fits in the trunk of most cars so you can bring it wherever you want to rid.</li>\n<li data-mce-fragment=\"1\">\n<strong data-mce-fragment=\"1\">Durability</strong>: 8.5″ Pneumatic tire no worry air leakage. Waterproof IP54 allows you to drive in rain. The control panel displays the speed, gear, mileage, and battery level.</li>\n<li data-mce-fragment=\"1\">\n<strong data-mce-fragment=\"1\">Fast Delivery and Warranty</strong>: Deliver within 2 to 5 business days. The e-scooter can be used for commuting or short-distance travel and is also an ideal gift for your friends and family. We provide a 180 days after-sales guarantee. If you have any questions about this product, please contact us at any time, and we will reply to you within 24 hours.</li>\n</ul>\n<div id=\"gtx-trans\" style=\"position: absolute; left: -18px; top: -18.4062px;\">\n<div class=\"gtx-trans-icon\"></div>\n</div><p>Trail Edition 2 for the off road scooter catalog.</p>"}'::jsonb, '275.39', '509.99', 23, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/25d98aee3cc7b9ca6b9c7c87a774b4a2.jpg?v=1701686548', FALSE, '{"en": ["HOT", "Spring Sale"], "zh": ["HOT", "Spring Sale"]}'::jsonb, '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/25d98aee3cc7b9ca6b9c7c87a774b4a2.jpg?v=1701686548", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/71rNiDoqdhL._AC_SL1500.jpg?v=1701686548", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/61H-rIMRI3L._AC_SL1500.jpg?v=1701686548", "https://cdn.shopify.com/s/files/1/0588/3592/7218/products/8743e979-4225-4b61-999d-a9ca52a4ed2a_1_6fccd8b4-92c8-4aea-8c1c-a79b552b2238.jpg?v=1701686548", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/6177TwCwkFL._AC_SL1500.jpg?v=1701686548", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/71cevG2IfFL._AC_SL1500.jpg?v=1701686548", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/7105Eb8gOEL._AC_SL1500.jpg?v=1701686548", "https://cdn.shopify.com/s/files/1/0588/3592/7218/products/f3c2b8cf-7fa8-443a-a8e4-a54f65e33de7_1_b646eeb8-caaa-43c1-a