INSERT INTO pms_sku (product_id, sku_code, price, compare_at_price, stock, pic, images, description, specs, status) VALUES ((SELECT id FROM pms_product WHERE slug = 'isinwheel-s4-electric-scooter-for-kids-ages-6-14-commuter-electric-scooter'), '3964832-COMMUTER-ELECTRIC-SCOOTER-11-5-12626F7E0A18', '189.99', '229.99', 0, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/ce5e39403ae049d28ab5982736412c21.png?v=1764831128', '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/ce5e39403ae049d28ab5982736412c21.png?v=1764831128"]'::jsonb, '{"en": "isinwheel S4 Electric Scooter for Kids Ages 6-14 - Purple", "zh": "isinwheel S4 Electric Scooter for Kids Ages 6-14 - Purple"}'::jsonb, '{"en": {"color": "Purple"}, "zh": {"color": "Purple"}}'::jsonb, 'INACTIVE') ON CONFLICT (sku_code) DO UPDATE SET product_id = EXCLUDED.product_id, price = EXCLUDED.price, compare_at_price = EXCLUDED.compare_at_price, stock = EXCLUDED.stock, pic = EXCLUDED.pic, images = EXCLUDED.images, description = EXCLUDED.description, specs = EXCLUDED.specs, status = EXCLUDED.status, update_time = CURRENT_TIMESTAMP;
INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (11, 'isinwheel-2in1-electric-scooter-for-kids-ages-3-12-new-commuter-electric-scooter', '{"en": "isinwheel Long Range 3 Wheel Kids Electric Scooter", "zh": "isinwheel Long Range 3 Wheel Kids Electric Scooter"}'::jsonb, '{"en": "Commuter Scooter", "zh": "Commuter Scooter"}'::jsonb, '{"en": "<div style=\"text-align: left;\" data-mce-style=\"text-align: left;\">\n<img src=\"https://cdn.shopifycdn.net/s/files/1/0588/3592/7218/files/A_-970x600-01.jpg?v=1651730847\" alt=\"\" style=\"float: none;\" data-mce-style=\"float: none;\"><span data-mce-fragment=\"1\">The iSinwheel® Long Range 3 Wheel is a specially designed electric scooter for kids, focusing on safety, stability, and extended range. It allows children to enjoy hours of outdoor fun while ensuring their safety and comfort during the ride.</span>\n</div>\n<div style=\"text-align: left;\" data-mce-style=\"text-align: left;\"><img alt=\"\" src=\"https://cdn.shopifycdn.net/s/files/1/0588/3592/7218/files/A_-970x300-01.jpg?v=1651732045\"></div>\n<ul>\n<li>【<strong>New Upgraded High Performance Kids Scooter</strong>】: iSinwheel kid''s electric scooter is suitable for kids aged 3-12 years old, with a newly upgraded accelerator, the kids only need to gently glide, it can successfully accelerate, bringing your kids a pleasant time.</li>\n<li>【<strong>Safety &amp; Comfortable</strong>】: parents will be relieved by the built-in safety features like a rear brake. Kids just press it to stop the kick scooter slowly and safely during riding. And the Handlebars with comfortable rubber material offers kids increased control and ensure a safe and not easy to slip.</li>\n<li>【<strong>Long Battery Life</strong>】: MINI electric scooter for kids provides longer battery life, which allows children to fully enjoy the fun of riding. No need to constantly push off with their feet to create movement, Just stand on the foot deck with one foot and push off with your foot to start gliding, the electric scooter will move forward with safe speed not exceeding 8.5mph, and the capacity for trips up to 19 miles on one charge.</li>\n<li>【<strong>Fantastic LED Flashing Wheels</strong>】: No battery needed. The front 2 wheels are designed as a self-generated power system. they will automatically light up when kids start to ride that shines bright and stands out. Your kids will love this special feature and have a lot of fun while playing.</li>\n<li>【<strong>Lean To Steer Mechanism</strong>】: Helps your child develop balance skills, coordination, and more. The Electric Scooter features easy maneuvering with lean-to-steer technology, which means the kid''s scooter is controlled by leaning rather than turning the steering wheel.</li>\n<li>【<strong>Adjustable Handlebar</strong>】: Grow With Your Kids. MINI electric scooter for kids has 3 levels adjustable height to suit your child as grown. Easily adjust the handlebars to heights between 24.8\"- 33.8\", electric scooter which very suitable for kids 3 to 12 years old.</li>\n<li>【<strong>A great gift for your child</strong>】: Whether your kid is brand new to scooters or ready to upgrade to a more advanced model, they will love the independence of cruising around on their own. The iSinwheel electric scooter will be perfect for kids, get the kids to enjoy the fun of gliding.</li>\n</ul>\n<ul class=\"subtitle-features\"></ul>\n<table border=\"1\" style=\"width: 534px;\" height=\"430\" data-mce-fragment=\"1\" data-mce-style=\"width: 534px;\">\n<tbody data-mce-fragment=\"1\">\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><strong>Specification</strong></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\"><strong>Parameters</strong></td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><span data-mce-fragment=\"1\">Model </span></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">Mini Kids Electric Scooter</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><span data-mce-fragment=\"1\">Recommended Age</span></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">3-12 <span data-mce-fragment=\"1\">years old</span>\n</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><span data-mce-fragment=\"1\">Max Speed</span></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">\n<span data-mce-fragment=\"1\">8.5</span>mph (13.9km/h)</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><span data-mce-fragment=\"1\">Max  Range </span></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">19miles</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><span data-mce-fragment=\"1\">Max Incline</span></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">15<span data-mce-fragment=\"1\">°</span>\n</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><span data-mce-fragment=\"1\">Net Weight</span></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">3.7kg/8.2lbs</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><span data-mce-fragment=\"1\">Gross Weight</span></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">4.6kg/10.1lbs</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><span data-mce-fragment=\"1\">Package Dimensions</span></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">63.5*16.5*34cm/25*6.5*13.4inches</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><span data-mce-fragment=\"1\">Max Load</span></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">40kg/88.2lbs</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\">Scooter <span data-mce-fragment=\"1\">Dimensions</span>\n</td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">62*31.5*90cm/24.4*12.4*35.4inches</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\">Battery Specification</td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">12.8-14.6V 5Ah 64WH</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\">Charge Requirement</td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">100-240V 50-60HZ</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><span data-mce-fragment=\"1\">Charging time</span></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">4H</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\">Wheel Material</td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">Flashing PU Wheel+ Rubber wheel</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><span data-mce-fragment=\"1\">Braking</span></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\">Foot brake</td>\n</tr>\n<tr data-mce-fragment=\"1\">\n<td style=\"width: 254.031px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 254.031px;\"><span data-mce-fragment=\"1\">IP Rating</span></td>\n<td style=\"width: 261.969px;\" data-mce-fragment=\"1\" data-mce-style=\"width: 261.969px;\"><span data-mce-fragment=\"1\">IP64</span></td>\n</tr>\n</tbody>\n</table>\n<p><img src=\"https://cdn.shopifycdn.net/s/files/1/0588/3592/7218/files/Mini_Blue_A__B2_V01_220511.jpg?v=1652343283\" alt=\"\"><img alt=\"\" src=\"https://cdn.shopifycdn.net/s/files/1/0588/3592/7218/files/Mini_Blue_A__B1_V01_220511.jpg?v=1652342420\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0588/3592/7218/files/Mini_Blue_A__B1_V01_220511.jpg?v=1652342420\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0588/3592/7218/files/Mini_Blue_B2_V01_220511.jpg?v=1652341768\" alt=\"\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0588/3592/7218/files/Mini_Pink_B3_V01_220512.jpg?v=1652341902\" alt=\"\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0588/3592/7218/files/Mini_Pink_B3_V01_220512.jpg?v=1652341902\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0588/3592/7218/files/Mini_Blue_B5_V01_220511.jpg?v=1652341939\" alt=\"\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0588/3592/7218/files/A_-970x600-03.jpg?v=1651732295\" alt=\"\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/