INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (11, 'isinwheel-gt2-off-road-electric-scooter-peak-1000w-commuter-electric-scooter', '{"en": "isinwheel GT2 1000W Off Road Electric Scooter 2026 Upgraded Version", "zh": "isinwheel GT2 1000W Off Road Electric Scooter 2026 Upgraded Version"}'::jsonb, '{"en": "Commuter Scooter", "zh": "Commuter Scooter"}'::jsonb, '{"en": "<div class=\"product-block\" data-mce-fragment=\"1\">\n<div class=\"rte\" data-mce-fragment=\"1\">\n<div style=\"text-align: left;\" data-mce-fragment=\"1\" data-mce-style=\"text-align: left;\">\n<h3 data-mce-fragment=\"1\">\n<strong> The ultimate all-terrain electric scooter</strong><br>\n</h3>\n<p style=\"display: flex; align-items: center;\" data-mce-fragment=\"1\" data-mce-style=\"display: flex; align-items: center;\"><span style=\"font-size: 0.875rem;\"><strong>isinwheel GT2 off-road scooter starts a whole new perspective where a scooter could be the new sports equipment. The GT2 comes with a cyberpunk design concept and a structure that uses aircraft-grade magnesium alloy that can support a maximum payload of 330lbs. Safety is not an issue as the gt2 off road electric scooter uses front and rear disc brakes on self-healing 11-inch pneumatic off road Tires. The gt2 can accelerate up to 28mph and has a super long range of around 28 miles, making it the most powerful and best off road electric scooter ever released. This high-performance, high-tech model is sure to turn heads your way</strong></span></p>\n<div style=\"display: flex; align-items: center;\" data-mce-fragment=\"1\" data-mce-style=\"display: flex; align-items: center;\"><br data-mce-fragment=\"1\"></div>\n</div>\n</div>\n</div>\n<div class=\"product-block\" data-mce-fragment=\"1\">\n<div class=\"product-form__texts\" data-mce-fragment=\"1\">\n<div class=\"pro