INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (11, 'isinwheel-s9-pro-electric-scooter-1-commuter-electric-scooter', '{"en": "isinwheel S9Pro Electric Scooter 350W", "zh": "isinwheel S9Pro Electric Scooter 350W"}'::jsonb, '{"en": "Commuter Scooter", "zh": "Commuter Scooter"}'::jsonb, '{"en": "<p>The iSinwheel S9Pro is a 350W electric scooter designed to provide a perfect balance of speed, efficiency, and comfort. Its sleek design, reliable power output, and smooth ride make it a great choice for daily urban commuting and short trips.</p>\n<p> </p>\n<img data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/05c1749392567beef34c8b7bbb8c21ac_349fd0a5-731e-4fb6-800d-612e8b4f1430.png?v=1615529880\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/05c1749392567beef34c8b7bbb8c21ac_349fd0a5-731e-4fb6-800d-612e8b4f1430.png?v=1615529880\"><span data-mce-fragment=\"1\">Max speed 18.6mph (30km/h)</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/06600783af0273abb34e0a0afee8a06b_41f17ca0-7d62-4c3d-a4f8-783805cac284.png?v=1615530248\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/06600783af0273abb34e0a0afee8a06b_41f17ca0-7d62-4c3d-a4f8-783805cac284.png?v=1615530248\"><span data-mce-fragment=\"1\">Max range 15.5 miles (25km)</span><br data-mce-fragment=\"1\"><img src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/3b49dcc1eb4b18b6fa150e99d1621f22.png?v=1615530287\" data-mce-fragment=\"1\" data-mce-src=\"https://cdn.shopifycdn.net/s/files/1/0536/2417/6817/files/3b49dcc1eb4b18b6fa150e99d1621f22.png?v=1615530287\"><span data-mce-fragment=\"1\">8.5inch Honeycomb solid tire</span><br data-mce-fragment=\"1\"