INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (11, 'led-side-light-strip-for-v10-off-road-electric-longboard-26cm-length-velcro-mount-2-in-1-charging-cable-commuter-electric-scooter', '{"en": "LED Side Light Strip for V10 Off-Road Electric Longboard (10 inch Length, Velcro Mount)", "zh": "LED Side Light Strip for V10 Off-Road Electric Longboard (10 inch Length, Velcro Mount)"}'::jsonb, '{"en": "Commuter Scooter", "zh": "Commuter Scooter"}'::jsonb, '{"en": "<ul>\n<li>\n<p><strong>Versatile Compatibility:</strong> Specifically designed for the V10-type off-road electric longboard scooter but also compatible with other off-road longboards, provided they have sufficient space for installation.</p>\n</li>\n<li>\n<p><strong>Ideal Dimensions:</strong> The LED strip fits perfectly within a 10inch by 0.98inch space, offering a sleek and low-profile enhancement that doesn’t add bulk to your board.</p>\n</li>\n<li>\n<p><strong>Secure Mounting:</strong> Features a Velcro mounting system for easy attachment and removal, ensuring the LED strip stays securely in place, even on rough terrains.</p>\n</li>\n<li>\n<p><strong>Convenient Charging:</strong> Comes with a 2-in-1 charging cable, making it simple to power up your lights without the need for extra accessories.</p>\n</li>\n<li>\n<p><strong>Durable Packaging:</strong> Shipped in a sturdy airplane box, ensuring your LED light strip arrives safely and is well-protected during transit.</p>\n</li>\n</ul>", "zh": "<ul>\n<li>\n<p><strong>Versatile Compatibility:</strong> Specifically designed for the V10-type off-road electric longboard scooter but also compatible with other off-road longboards, provided they have sufficient space for installation.</p>\n</li>\n<li>\n<p><strong>Ideal Dimensions:</strong> The LED strip fits perfectly within a 10inch by 0.98inch space, offering a sleek and low-profile enhancement that doesn’t add bulk to your board.</p>\n</li>\n<li>\n<p><strong>Secure Mounting:</strong> Features a Velcro mounting system for easy attachment and removal, ensuring the LED strip stays securely in place, even on rough terrains.</p>\n</li>\n<li>\n<p><strong>Convenient Charging:</strong> Comes with a 2-in-1 charging cable, making it simple to power up your lights without the need for extra accessories.</p>\n</li>\n<li>\n<p><strong>Durable Packaging:</strong> Shipped in a sturdy airplane box, ensuring your LED light strip arrives safely and is well-protected during transit.</p>\n</li>\n</ul>"}'::jsonb, '59.99', '89.99', 20, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/DSC8197.jpg?v=1726024132', FALSE, '{"en": ["Spring Sale"], "zh": ["Spring Sale"]}'::jsonb, '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/DSC8197.jpg?v=1726024132", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/DSC8198.jpg?v=1726024132", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/DSC8207.jpg?v=1734075866", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/DSC8210.jpg?v=1734075866", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/DSC8215.jpg?v=1734075866", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/DSC8217.jpg?v=1734075866", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/DSC8222.jpg?v=1734075866"]'::jsonb, '', '{"en": [{"label": "Collection", "value": "Commuter Scooter", "icon": "NavigationIcon"}, {"label": "Variants", "value": "1", "icon": "ActivityIcon"}, {"label": "Vendor", "value": "iSinwheel Official Store", "icon": "ZapIcon"}, {"label": "Availability", "value": "In stock", "icon": "BatteryIcon"}], "zh": [{"label": "Collection", "value": "Commuter Scooter", "icon": "NavigationIcon"}, {"label": "Variants", "value": "1", "icon": "ActivityIcon"}, {"label": "Vendor", "value": "iSinwheel Official Store", "icon": "ZapIcon"}, {"label": "Availability", "value": "In sto