INSERT INTO pms_sku (product_id, sku_code, price, compare_at_price, stock, pic, images, description, specs, status) VALUES ((SELECT id FROM pms_product WHERE slug = 'isinwheel-s10max-1000w-high-end-commuting-electric-scooter-commuter-electric-scooter-2'), '5349907-COMMUTER-ELECTRIC-SCOOTER-49-1-2E7993B8E1E4', '632.39', '917.99', 20, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/12_faef910f-ded6-40e8-87d1-15281d9e483c.jpg?v=1741664073', '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/12_faef910f-ded6-40e8-87d1-15281d9e483c.jpg?v=1741664073"]'::jsonb, '{"en": "isinwheel S10Max 1000W High-End Commuting Electric Scooter 2026 Upgraded Version / Urban Edition 2", "zh": "isinwheel S10Max 1000W High-End Commuting Electric Scooter 2026 Upgraded Version / Urban Edition 2"}'::jsonb, '{"en": {"title": "Default Title"}, "zh": {"title": "Default Title"}}'::jsonb, 'ACTIVE') ON CONFLICT (sku_code) DO UPDATE SET product_id = EXCLUDED.product_id, price = EXCLUDED.price, compare_at_price = EXCLUDED.compare_at_price, stock = EXCLUDED.stock, pic = EXCLUDED.pic, images = EXCLUDED.images, description = EXCLUDED.description, specs = EXCLUDED.specs, status = EXCLUDED.status, update_time = CURRENT_TIMESTAMP;
INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (11, 'isinwheel-s9-pneumatic-tireelectric-scooter-commuter-electric-scooter-2', '{"en": "isinwheel S9 Pro Pneumatic Tire Electric Scooter - Urban Edition 2", "zh": "isinwheel S9 Pro Pneumatic Tire Electric Scooter - Urban Edition 2"}'::jsonb, '{"en": "Commuter Scooter / Urban Edition 2", "zh": "Commuter Scooter / Urban Edition 2"}'::jsonb, '{"en": "<p><span>The S9pro Electric Scooter is equipped with pneumatic tires, designed to absorb shocks and bumps, providing a smooth and comfortable ride across various urban terrains. Its design combines comfort, efficiency, and durability, making it ideal for daily commuting.</span></p>\n<p>【Strong Power Electric Scooters 】The S9 pro adult electric powered scooter features a quiet 350W brushless motor, boasting a top speed of 19 MPH with a stable driving experience.You can APP set zero start or non-zero start faster acceleration, easy climb on hills, and easy maneuverability.The power of the scooter can carry a weight of 264 lbs for riding.<br data-mce-fragment=\"1\">【APP Smart Controller】Download the free APP (iPhone &amp; Android) to connect your e-scooter via Bluetooth. This scooter for adult has a Bluetooth system. You can control via APP: lock/unlock, light on, gear, start mode (zero start or non-zero start), set maximum speed, cruise control, etc. This APP is a very smart software that can help you quickly use the electric scooters.<br data-mce-fragment=\"1\">【Dual Braking System】The e-scooter has a very responsive electronic hall brake and mechanical disc brake, which highly improves safety when in use. Equipped with headlights and rear brake light, helping you to be seen in the night with a bell enhanced safety when riding; front/rear lights reinforce your safety while riding at night or in places where visibility and safety are concerns.<br data-mce-fragment=\"1\">【8.5-inch Maintenance-free Tires】The electric scooter uses 8.5-inch pneumatic shock-absorbing tires with high elasticity and wears resistance. The honeycomb tire does not require inflation, repair, maintenance. And it''s don''t worry about punctures. It also has a good anti-slip effect.<br data-mce-fragment=\"1\">【Long-range Battery】High capacity battery(6 Ah ) delivers 17 miles on one charge of 5 hours, it is very reliable to get to where you need to go. The range may vary depending on riding conditions, rider''s weight, speed, and/or terrains. Smart Battery Management System assures battery safety and extends battery life.<br data-mce-fragment=\"1\">【Portable Folding Design】Fast folding system for easy portability. iSinwheel S9 electric scooter can be folded with ease in mere 3 seconds. More portable and less space-intensive when folded. The e-scooter is a great gift idea for recreational use, also a great alternative for anyone who has to do part of a commute to work on a train, bus, or school.</p><p>Urban Edition 2 for the commuter scooter catalog.</p>", "zh": "<p><span>The S9pro Electric Scooter is equipped with pneumatic tires, designed to absorb shocks and bumps, providing a smooth and comfortable ride across various urban terrains. Its design combines comfort, efficiency, and durability, making it ideal for daily commuting.</span></p>\n<p>【Strong Power Electric Scooters 】The S9 pro adult electric powered scooter features a quiet 350W brushless motor, boasting a top speed of 19 MPH with a stable driving experience.You can APP set zero start or non-zero start faster acceleration, easy climb on hills, and easy maneuverability.The power of the scooter can carry a weight of 264 lbs for riding.<br data-mce-fragment=\"1\">【APP Smart Controller】Download the free APP (iPhone &amp; Android) to connect your e-scooter via Bluetooth. This scooter for adult has a Bluetooth system. You can control via APP: lock/unlock, light on, gear, start mode (zero start or non-zero start), set maximum speed, cruise control, etc. This APP is a very smart software that can help you quickly use the electric scooters.<br data-mce-fragment=\"1\">【Dual Braking System】The e-scooter has a very responsive electronic hall brake and mechanical disc brake, which highly improves safety when in use. Equipped with headlights and rear brake light, helping you to be seen in the night with a bell enhanced safety when riding; front/rear lights reinforce your safety while riding at night or in places where visibility and safety are concerns.<br data-mce-fragment=\"1\">【8.5-inch Maintenance-free Tires】The electric scooter uses 8.5-inch pneumatic shock-absorbing tires with high elasticity and wears resistance. The honeycomb tire does not require inflation, repair, maintenance. And it''s don''t worry about punctures. It also has a good anti-slip effect.<br data-mce-fragment=\"1\">【Long-range Battery】High capacity battery(6 Ah ) delivers 17 miles on one charge of 5 hours, it is very reliable to get to where you need to go. The range may vary depending on riding conditions, rider''s weight, speed, and/or terrains. Smart Battery Management System assures battery safety and extends battery life.<br data-mce-fragment=\"1\">【Portable Folding Design】Fast folding system for easy portability. iSinwheel S9 electric scooter can be folded with ease in mere 3 seconds. More portable and less space-intensive when folded. The e-scooter is a great gift idea for recreational use, also a great alternative for anyone who has to do part of a commute to work on a train, bus, or school.</p><p>Urban Edition 2 for the commuter scooter catalog.</p>"}'::jsonb, '285.59', '407.99', 23, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_2_4beab83b-d28c-425e-b56e-ba0a8fb67495.jpg?v=1717063302', FALSE, '{"en": ["HOT", "Spring Sale"], "zh": ["HOT", "Spring Sale"]}'::jsonb, '["https://cdn.shopify.com/s/files/1/0588/3592/72