INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (14, 'isinwheel-u2-electric-cruiser-bike-1-all-terrain-electric-bikes-2', '{"en": "isinwheel U2 Electric Cruiser Bike - Explorer Edition 2", "zh": "isinwheel U2 Electric Cruiser Bike - Explorer Edition 2"}'::jsonb, '{"en": "Off Road & All Terrain / Explorer Edition 2", "zh": "Off Road & All Terrain / Explorer Edition 2"}'::jsonb, '{"en": "<span data-mce-fragment=\"1\">An U2 electric bike with a 45-mile range seamlessly blends classic cruiser bike aesthetics with modern electric technology. Featuring a powerful electric motor and a high-capacity battery, this e bike offers pedal-assist support, making longer rides and hilly terrains more accessible. Its comfortable design, wider tires, and ergonomic seating ensure a smooth and enjoyable journey. Ideal for leisurely rides and commuting alike,</span><p>Explorer Edition 2 for the off road & all terrain catalog.</p>", "zh": "<span data-mce-fragment=\"1\">An U2 electric bike with a 45-mile range seamlessly blends classic cruiser bike aesthetics with modern electric technology. Featuring a powerful electric motor and a high-capacity battery, this e bike offers pedal-assist support, making longer rides and hilly terrains more accessible. Its comfortable design, wider tires, and ergonomic seating ensure a smooth and enjoyable journey. Ideal for leisurely rides and commuting alike,</span><p>Explorer Edition 2 for the off road & all terrain catalog.</p>"}'::jsonb, '611.99', '815.99', 23, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_a8f6f98b-d949-4eda-b1f3-922818a074bd.png?v=1723802389', FALSE, '{"en": ["HOT", "Spring Sale"], "zh": ["HOT", "Spring Sale"]}'::jsonb, '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_a8f6f98b-d949-4eda-b1f3-922818a074bd.png?v=1723802389", "https://cd