INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (13, 'isinwheel-u2-electric-cruiser-bike-1-commuter-ebikes', '{"en": "isinwheel U2 Electric Cruiser Bike", "zh": "isinwheel U2 Electric Cruiser Bike"}'::jsonb, '{"en": "Commuter & City Road", "zh": "Commuter & City Road"}'::jsonb, '{"en": "<span data-mce-fragment=\"1\">An U2 electric bike with a 45-mile range seamlessly blends classic cruiser bike aesthetics with modern electric technology. Featuring a powerful electric motor and a high-capacity battery, this e bike offers pedal-assist support, making longer rides and hilly terrains more accessible. Its comfortable design, wider tires, and ergonomic seating ensure a smooth and enjoyable journey. Ideal for leisurely rides and commuting alike,</span>", "zh": "<span data-mce-fragment=\"1\">An U2 electric bike with a 45-mile range seamlessly blends classic cruiser bike aesthetics with modern electric technology. Featuring a powerful electric motor and a high-capacity battery, this e bike offers pedal-assist support, making longer rides and hilly terrains more accessible. Its comfortable design, wider tires, and ergonomic seating ensure a smooth and enjoyable journey. Ideal for leisurely rides and commuting alike,</span>"}'::jsonb, '599.99', '799.99', 20, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_0a15757d-d9c0-4868-a283-d3a1d1f93fd4.png?v=1723802389', FALSE, '{"en": ["HOT", "Spring Sale"], "zh": ["HOT", "Spring Sale"]}'::jsonb, '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_0a15757d-d9c0-4868-a283-d3a1d1f93fd4.png?v=1723802389", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_a8f6f98b-d949-4eda-b1f3-922818a074bd.png?v=1723802389", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_10_bb19b3f3-c7fb-4a54-a8f7-a7ea9a69001a.jpg?v=1711597127", "https://cd