INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (13, 'isinwheel-u2-electric-cruiser-bike-commuter-ebikes-4', '{"en": "isinwheel U2 Electric Cruiser Bike - Commuter Plus 2", "zh": "isinwheel U2 Electric Cruiser Bike - Commuter Plus 2"}'::jsonb, '{"en": "Commuter & City Road / Commuter Plus 2", "zh": "Commuter & City Road / Commuter Plus 2"}'::jsonb, '{"en": "<span data-mce-fragment=\"1\">An U2 electric bike with a 45-mile range seamlessly blends classic cruiser bike aesthetics with modern electric technology. Featuring a powerful electric motor and a high-capacity battery, this e bike offers pedal-assist support, making longer rides and hilly terrains more accessible. Its comfortable design, wider tires, and ergonomic seating ensure a smooth and enjoyable journey. Ideal for leisurely rides and commuting alike,</span><p>Commuter Plus 2 for the commuter & city road catalog.</p>", "zh": "<span data-mce-fragment=\"1\">An U2 electric bike with a 45-mile range seamlessly blends classic cruiser bike aesthetics with modern electric technology. Featuring a powerful electric motor and a high-capacity battery, this e bike offers pedal-assist support, making longer rides and hilly terrains more accessible. Its comfortable design, wider tires, and ergonomic seating ensure a smooth and enjoyable journey. Ideal for leisurely rides and commuting alike,</span><p>Commuter Plus 2 for the commuter & city road catalog.</p>"}'::jsonb, '635.99', '847.99', 29, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_10_0d1b298b-99e1-4c88-a0f6-0d2dbb632a09.jpg?v=1703815321', FALSE, '{"en": ["HOT", "Spring Sale"], "zh": ["HOT", "Spring Sale"]}'::jsonb, '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/1_10_0d1b298b-99e1-4c88-a0f6-0d2dbb632a09.jpg?v=1703815321", "https://cdn.shopify.com/s/files/1/0588/3592