INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (16, 'isinwheel-v8-1200w-electric-skateboard-with-portable-removable-battery-remote-control-all-terrain-electric-skateboards', '{"en": "isinwheel V8 1200W Electric Skateboard with Portable Removable Battery & Remote Control", "zh": "isinwheel V8 1200W Electric Skateboard with Portable Removable Battery & Remote Control"}'::jsonb, '{"en": "Off Road & Terrain", "zh": "Off Road & Terrain"}'::jsonb, '{"en": "Upgraded Powerful Motor - isinwheel electric skateboard is equipped with a powerful hub motor, which generates a top speed of 28 mph and a range of 11 miles to adapt accordingly to different situations like climbing hills, grass surface, or riding inside the city.<br data-mce-fragment=\"1\">4 Ride Speeds and 2 Modes - The new ESC with a responsive control system provides the rider with a smooth braking experience. In addition, the skateboard is IPX6 waterproof, you can switch between 2 modes to suit your daily activities, for riders with different needs, we have designed 4 speeds to best meet your needs.<br data-mce-fragment=\"1\">Quick Charging - The skateboard supports 2 A fast charging, it only takes about 2 hours to charge, allowing you to spend more time playing instead of worrying about the battery.<br data-mce-fragment=\"1\">Big Wheels Are Safer - The V8 changed the wheels to 105mm, which can easily adapt to different road conditions (climbing, grass, or riding in the city), allowing you to enjoy the pleasure of speed while giving you more security.<br data-mce-fragment=\"1\">Reliable After-Sales - If you encounter any problems, please contact us at the first time, we provide you with 6 months no reason to replace and 12 months warranty, your satisfactory experience is the encouragement of our progress.", "zh": "Upgraded Powerful Motor - isinwheel electric skateboard is equipped with a powerful hub motor, which generates a top speed of 28 mph and a range of 11 miles to adapt accordingly to different situations like climbing hills, grass surface, or riding inside the city.<br data-mce-fragment=\"1\">4 Ride Speeds and 2 Modes - The new ESC with a responsive control system provides the rider with a smooth braking experience. In addition, the skateboard is IPX6 waterproof, you can switch between 2 modes to suit your daily activities, for riders with different needs, we have designed 4 speeds to best meet your needs.<br data-mce-fragment=\"1\">Quick Charging - The skateboard supports 2 A fast charging, it only takes about 2 hours to charge, allowing you to spend more time playing instead of worrying about the battery.<br data-mce-fragment=\"1\">Big Wheels Are Safer - The V8 changed the wheels to 105mm, which can easily adapt to different road conditions (climbing, grass, or riding in the city), allowing you to enjoy the pleasure of speed while giving you more security.<br data-mce-fragment=\"1\">Reliable After-Sales - If you encounter any problems, please contact us at the first time, we provide you with 6 months no reason to replace and 12 months warranty, your satisfactory experience is the encouragement of our progress."}'::jsonb, '379.99', '599.99', 20, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/SKU-01-V8withBattery_1.jpg?v=1720515710', FALSE, '{"en": ["Spring Sale"], "zh": ["Spring Sale"]}'::jsonb, '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/SKU-01-V8withBattery_1.jpg?v=1720515710", "https://cdn.shopify.com/s/files/1/0588/3592/7218/products/V8backlight.jpg?v=1716371473", "https://cdn.shopify.com/s/files/1/0588/3592/7218/products/03_1.jpg?v=1716371473", "https://cdn.shopify.com/s/files/1/0588/3592/7218/products/07_ac466073-9e00-4aca-bb28-8afa52e8542a.jpg?v=1716371473", "https://cdn.shopify.com/s/files/1/0588/3592/7218/products/4_1.jpg?v=1716371473", "https://cdn.shopif