INSERT INTO pms_sku (product_id, sku_code, price, compare_at_price, stock, pic, images, description, specs, status) VALUES ((SELECT id FROM pms_product WHERE slug = 'isinwheel-v10-off-road-electric-skateboard-with-ambient-light-remote-control-all-terrain-electric-skateboards-7'), '3778090-ALL-TERRAIN-ELECTRIC-SKATEBOARDS-27-1-F5DF2CFAF36E', '617.49', '1044.99', 20, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/86f6be2c1d9de00105debe114aa0d2bb_1eb38b4a-8dac-4dc8-8f24-255c0e0432de.jpg?v=1759981429', '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/86f6be2c1d9de00105debe114aa0d2bb_1eb38b4a-8dac-4dc8-8f24-255c0e0432de.jpg?v=1759981429"]'::jsonb, '{"en": "isinwheel V10 Off Road Electric Skateboard with Ambient Light & Remote Control / Terrain Edition 3", "zh": "isinwheel V10 Off Road Electric Skateboard with Ambient Light & Remote Control / Terrain Edition 3"}'::jsonb, '{"en": {"title": "Default Title"}, "zh": {"title": "Default Title"}}'::jsonb, 'ACTIVE') ON CONFLICT (sku_code) DO UPDATE SET product_id = EXCLUDED.product_id, price = EXCLUDED.price, compare_at_price = EXCLUDED.compare_at_price, stock = EXCLUDED.stock, pic = EXCLUDED.pic, images = EXCLUDED.images, description = EXCLUDED.description, specs = EXCLUDED.specs, status = EXCLUDED.status, update_time = CURRENT_TIMESTAMP;
INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (16, 'isinwheel-v8-1200w-electric-skateboard-with-portable-removable-battery-remote-control-all-terrain-electric-skateboards-7', '{"en": "isinwheel V8 1200W Electric Skateboard with Portable Removable Battery & Remote Control - Terrain Edition 3", "zh": "isinwheel V8 1200W Electric Skateboard with Portable Removable Battery & Remote Control - Terrain Edition 3"}'::jsonb, '{"en": "Off Road & Terrain / Terrain Edition 3", "zh": "Off Road & Terrain / Terrain Edition 3"}'::jsonb, '{"en": "Upgraded Powerful Motor - isinwheel electric skateboard is equipped with a powerful hub motor, which generates a top speed of 28 mph and a range of 11 miles to adapt accordingly to different situations like climbing hills, grass surface, or riding inside the city.<br data-mce-fragment=\"1\">4 Ride Speeds and 2 Modes - The new ESC with a responsive control system provides the rider with a smooth braking experience. In addition, the skateboard is IPX6 waterproof, you can switch between 2 modes to suit your daily activities, for riders with different needs, we have designed 4 speeds to best meet your needs.<br data-mce-fragment=\"1\">Quick Charging - The skateboard supports 2 A fast charging, it only takes about 2 hours to charge, allowing you to spend more time playing instead of worrying about the battery.<br data-mce-fragment=\"1\">Big Wheels Are Safer - The V8 changed the wheels to 105mm, which can easily adapt to different road conditions (climbing, grass, or riding in the city), allowing you to enjoy the pleasure of speed while giving you more security.<br data-mce-fragment=\"1\">Reliable After-Sales - If you encounter any problems, please contact us at the first time, we provide you with 6 months no reason to replace and 12 months warranty, your satisfactory experience is the encouragement of our progress.<p>Terrain Edition 3 for the off road & terrain catalog.</p>", "zh": "Upgraded Powerful Motor - isinwheel electric skateboard is equipped with a powerful hub motor, which generates a top speed of 28 mph and a range of 11 miles to adapt accordingly to different situations like climbing hills, grass surface, or riding inside the city.<br data-mce-fragment=\"1\">4 Ride Speeds and 2 Modes - The new ESC with a responsive control system provides the rider with a smooth braking experience. In addition, the skateboard is IPX6 waterproof, you can switch between 2 modes to suit your daily activities, for riders with different needs, we have designed 4 speeds to best meet your needs.<br data-mce-fragment=\"1\">Quick Charging - The skateboard supports 2 A fast charging, it only takes about 2 hours to charge, allowing you to spend more time playing instead of worrying about the battery.<br data-mce-fragment=\"1\">Big Wheels Are Safer - The V8 changed the wheels to 105mm, which can easily adapt to different road conditions (climbing, grass, or riding in the city), allowing you to enjoy the pleasure of speed while giving you more security.<br data-mce-fragment=\"1\">Reliable After-Sales - If you encounter any problems, please contact us at the first time, we provide you with 6 months no reason to replace and 12 months warranty, your satisfactory experience is the encouragement of our progress.<p>Terrain Edition 3 for the off road & terrain catalog.</p>"}'::jsonb, '360.99', '569.99', 26, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/products/14_1.jpg?v=1716371473', FALSE, '{"en": ["Spring Sale"], "zh": ["Spring Sale"]}'::jsonb, '["https://cdn.shopify.com/s/files/1/0588/3592/7218/products/14_1.jpg?v=1716371473", "https://cdn.shopify.com/s/files/1/0588/3592/7218/products/3_77953df6-564b-49e5-b397-5cabfc77759a.jpg?v=1716371473", "https://cdn.shopify.com/s/files/1/0588/3592/7218/products/15.jpg?v=1716371473", "https://cdn.shopify.c