INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (15, 'isinwheel-v8-1200w-electric-skateboard-with-portable-removable-battery-remote-control-electric-skateboards-11', '{"en": "isinwheel V8 1200W Electric Skateboard with Portable Removable Battery & Remote Control - Campus Mode 3", "zh": "isinwheel V8 1200W Electric Skateboard with Portable Removable Battery & Remote Control - Campus Mode 3"}'::jsonb, '{"en": "Street & Carving / Campus Mode 3", "zh": "Street & Carving / Campus Mode 3"}'::jsonb, '{"en": "Upgraded Powerful Motor - isinwheel electric skateboard is equipped with a powerful hub motor, which generates a top speed of 28 mph and a range of 11 miles to adapt accordingly to different situations like climbing hills, grass surface, or riding inside the city.<br data-mce-fragment=\"1\">4 Ride Speeds and 2 Modes - The new ESC with a responsive control system provides the rider with a smooth braking experience. In addition, the skateboard is IPX6 waterproof, you can switch between 2 modes to suit your daily activities, for riders with different needs, we have designed 4 speeds to best meet your needs.<br data-mce-fragment=\"1\">Quick Charging - The skateboard supports 2 A fast charging, it only takes about 2 hours to charge, allowing you to spend more time playing instead of worrying about the battery.<br data-mce-fragment=\"1\">Big Wheels Are Safer - The V8 changed the wheels to 105mm, which can easily adapt to different road conditions (climbing, grass, or riding in the city), allowing you to enjoy the pleasure of speed while giving you more security.<br data-mce-fragment=\"1\">Reliable After-Sales - If you encounter any problems, please contact us at the first time, we provide you with 6 months no reason to replace and 12 months warranty, your satisfactory experience is the encouragem