INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (17, 'isinwheel-10-ah-battery-for-m10-electric-bike-e-bike-accessories', '{"en": "isinwheel 10 Ah battery for M10 Electric Bike", "zh": "isinwheel 10 Ah battery for M10 Electric Bike"}'::jsonb, '{"en": "E-bike Accessories", "zh": "E-bike Accessories"}'::jsonb, '{"en": "<p><span>Never cut your adventures short again with the Isinwheel 10 Ah battery designed for the M10 Electric Bike. This high-capacity battery extends your ebike''s range, allowing you to explore further and enjoy your rides longer. More power, more adventure, more fun!</span></p>\n<p><span style=\"color: rgb(255, 42, 0);\"><strong data-start=\"256\" data-end=\"265\">Note:</strong> The M10 comes in two different versions. If you need to purchase an M10 battery, please contact our customer service first to confirm your M10 version and ensure compatibility.</span></p>\n<p> </p>\n<p> </p>\n<div id=\"gtx-trans\" style=\"position: absolute; left: 328px; top: 49.1875px;\">\n<div class=\"gtx-trans-icon\"><br></div>\n</div>", "zh": "<p><span>Never cut your adventures short again with the Isinwheel 10 Ah battery designed for the M10 Electric Bike. This high-capacity battery extends your ebike''s range, allowing you to explore further and enjoy your rides longer. More power, more adventure, more fun!</span></p>\n<p><span style=\"color: rgb(255, 42, 0);\"><strong data-start=\"256\" data-end=\"265\">Note:</strong> The M10 comes in two different versions. If you need to purchase an M10 battery, please contact our customer service first to confirm your M10 version and ensure compatibility.</span></p>\n<p> </p>\n<p> </p>\n<div id=\"gtx-trans\" style=\"position: absolute; left: 328px; top: 49.1875px;\">\n<div class=\"gtx-trans-icon\"><br></div>\n</div>"}'::jsonb, '189.99', '229.99', 20, 'htt