INSERT INTO pms_product (category_id, slug, name, subtitle, description, price, compare_at_price, stock, pic, is_new, tags, images, app_image, specs, quick_know, upsells, spec_table, box_items, faqs, published, sort_order) VALUES (18, 'adjustable-electric-scooter-seat-saddle-e-scooter-accessories', '{"en": "Adjustable Electric Scooter Seat Saddle for S9/S9pro/S9 MAX", "zh": "Adjustable Electric Scooter Seat Saddle for S9/S9pro/S9 MAX"}'::jsonb, '{"en": "E-scooter Accessories", "zh": "E-scooter Accessories"}'::jsonb, '{"en": "<p><span>Upgrade your S9 series scooter experience with the Adjustable Electric Scooter Seat Saddle for S9/S9pro/S9 MAX. This essential accessory allows you to tailor the saddle height for optimal comfort, making extended journeys more enjoyable and less strenuous.</span></p>\n<ul data-mce-fragment=\"1\">\n<li data-mce-fragment=\"1\">High-quality cushion saddle seat provides excellent comfort: soft and breathable ergonomic sponge saddle seat with widened design makes riding comfortable and enjoyable.</li>\n<li data-mce-fragment=\"1\">Adjustable seat height: Suitable for 8.5-inch board width 14-15.5cm board thickness within 1.3cm. The seat can be adjusted to 20 - 24 inches to fit for various heights and ages (14+ years old) of riders.</li>\n<li data-mce-fragment=\"1\">Easy to Install &amp; Detachable: add-on saddle seat comes with screws, no additional drilling.</li>\n<li data-mce-fragment=\"1\">Easy to install and detach from the isinwheel s9, S9 Pro, S9max decks.</li>\n</ul>\n<p data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">Scooter Seat Installation Video🎬 </strong></p>\n<p data-mce-fragment=\"1\"><iframe title=\"YouTube video player\" src=\"https://www.youtube.com/embed/g_KH5PueYgQ\" width=\"100%\" height=\"360\" allowfullscreen=\"\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" frameborder=\"0\"></iframe><br></p>", "zh": "<p><span>Upgrade your S9 series scooter experience with the Adjustable Electric Scooter Seat Saddle for S9/S9pro/S9 MAX. This essential accessory allows you to tailor the saddle height for optimal comfort, making extended journeys more enjoyable and less strenuous.</span></p>\n<ul data-mce-fragment=\"1\">\n<li data-mce-fragment=\"1\">High-quality cushion saddle seat provides excellent comfort: soft and breathable ergonomic sponge saddle seat with widened design makes riding comfortable and enjoyable.</li>\n<li data-mce-fragment=\"1\">Adjustable seat height: Suitable for 8.5-inch board width 14-15.5cm board thickness within 1.3cm. The seat can be adjusted to 20 - 24 inches to fit for various heights and ages (14+ years old) of riders.</li>\n<li data-mce-fragment=\"1\">Easy to Install &amp; Detachable: add-on saddle seat comes with screws, no additional drilling.</li>\n<li data-mce-fragment=\"1\">Easy to install and detach from the isinwheel s9, S9 Pro, S9max decks.</li>\n</ul>\n<p data-mce-fragment=\"1\"><strong data-mce-fragment=\"1\">Scooter Seat Installation Video🎬 </strong></p>\n<p data-mce-fragment=\"1\"><iframe title=\"YouTube video player\" src=\"https://www.youtube.com/embed/g_KH5PueYgQ\" width=\"100%\" height=\"360\" allowfullscreen=\"\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" frameborder=\"0\"></iframe><br></p>"}'::jsonb, '69.99', '89.99', 20, 'https://cdn.shopify.com/s/files/1/0588/3592/7218/files/isinwheel-official-store-s9-seat-adjustable-electric-scooter-seat-saddle-for-s9-s9pro-s9-max-34256090431666.jpg?v=1692084607', FALSE, '{"en": ["HOT", "Spring Sale"], "zh": ["HOT", "Spring Sale"]}'::jsonb, '["https://cdn.shopify.com/s/files/1/0588/3592/7218/files/isinwheel-official-store-s9-seat-adjustable-electric-scooter-seat-saddle-for-s9-s9pro-s9-max-34256090431666.jpg?v=1692084607", "https://cdn.shopify.com/s/files/1/0588/3592/7218/files/isinwheel-official-store-s9-seat-adjustable-electric-scooter-seat-saddle-for-s9-s9pro-s9-max-34256090595506.jpg?v=169208460